<script setup lang="ts">
import { ref, onMounted, watch } from 'vue'
import { get } from '../api'
const range=ref('7d'),category=ref(''),q=ref(''),page=ref(1),items=ref<any[]>([]),total=ref(0)
async function load(){const r=await get('/audit-logs',{range:range.value,category:category.value,q:q.value,page:page.value,page_size:20});items.value=r.items||[];total.value=r.total||0}
watch([range,category,q],()=>{page.value=1;load()});watch(page,load);onMounted(load)
const categories:any={login:'登录',account:'云账号',sync:'同步',user:'用户'}
</script><template><div class="page"><div class="page-head"><div><h1>审计日志</h1><p>登录与关键配置操作记录 · 保留 180 天</p></div><span class="muted">共 {{total}} 条记录</span></div><div class="card content"><div class="toolbar"><div class="cloud-segment"><button v-for="r in [{v:'today',t:'今天'},{v:'7d',t:'近 7 天'},{v:'30d',t:'近 30 天'}]" :key="r.v" :class="{active:range===r.v}" @click="range=r.v">{{r.t}}</button></div><el-select v-model="category" clearable placeholder="全部分类" style="width:150px"><el-option v-for="(label,key) in categories" :key="key" :value="key" :label="label"/></el-select><el-input v-model="q" clearable placeholder="搜索操作人、对象或 IP" style="width:260px"/></div><el-table :data="items"><el-table-column label="时间" width="180"><template #default="{row}"><span class="mono">{{new Date(row.created_at).toLocaleString('zh-CN')}}</span></template></el-table-column><el-table-column label="分类" width="105"><template #default="{row}">{{categories[row.category]||row.category}}</template></el-table-column><el-table-column prop="actor" label="操作人" width="120"/><el-table-column prop="action" label="操作" width="150"/><el-table-column prop="target" label="对象" min-width="170"/><el-table-column label="结果" width="95"><template #default="{row}"><span :class="row.result==='success'?'ok':'bad'">{{row.result==='success'?'成功':'失败'}}</span></template></el-table-column><el-table-column prop="ip" label="IP" width="145"/><el-table-column prop="detail" label="详情" min-width="180"/></el-table><div v-if="!items.length" class="empty">该时间范围内暂无审计记录</div><div class="pager"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next"/></div></div></div></template><style scoped>.content{padding:18px}.pager{display:flex;justify-content:space-between;align-items:center;padding-top:18px;color:var(--subtle);font-size:12px}.ok{color:var(--green)}.bad{color:var(--red)}</style>
